  var card = eligible.find(function(item) { return item.instanceId === choice; });
  if (!card) return { success: false, message: '选择的手牌已无法降费' };
  var currentCost = card.actionPointCost === undefined ? 2 : card.actionPointCost;
  card.baseActionPointCost = currentCost; card.actionPointCost = Math.max(1, currentCost - 1); card.temporaryCostReductionTurnNumber = battle.turn.turnNumber;
  return { success: true, message: caster.name + '发布征讨号令，' + (card.name || card.cardId) + '的AP消耗降至' + card.actionPointCost };
}
